/*
 * EXERCISE: BROKEN_GNL (Get Next Line)
 * 
 * DESCRIPTION:
 * Implement get_next_line that reads line by line from a file descriptor.
 * This version may contain special cases or intentional "bugs".
*/

#include "get_next_line.h"

char *ft_strchr(char *s, int c)
{
  int i = 0;
  while(s[i] != c)
    i++;
  if (s[i] == c)
    return s + i;
  else
    return NULL;
}

void *ft_memcpy(void *dest, const void *src, size_t n)
{
  while(--n > 0)
    ((char *)dest)[n - 1] = ((char *)src)[n - 1];
  return dest;
}

size_t ft_strlen(char *s)
{
  size_t res = 0;
  while (*s)
  {
    s++;
    res++;
  }
  return res;
}

int str_append_mem(char **s1, char *s2, size_t size2)
{
  size_t size1 = ft_strlen(*s1);
  char *tmp = malloc(size2 + size1 + 1);
  if (!tmp)
    return 0;
  ft_memcpy(tmp, *s1, size1);
  ft_memcpy(tmp + size1, s2, size2);
  tmp[size1 + size2] = '\0';
  free(*s1);
  *s1 = tmp;
  return 1; 
}

int str_append_str(char **s1, char *s2)
{
  return str_append_mem(s1, s2, ft_strlen(s2));
}

void *ft_memmove(void *dest, const void *src, size_t n)
{
  if (dest > src)
    return ft_memmove(dest, src, n);
  else if (dest == src)
    return dest;
  size_t i = ft_strlen((char *)src) - 1;
  while (i >= 0)
  {
    ((char *)dest)[i] = ((char *)src)[i];
    i--;
  }
  return dest;
}

char *get_next_line(int fd)
{
  static char b[BUFFER_SIZE + 1] = "";
  char *ret = NULL;
  char *tmp = ft_strchr(b, '\n');
  while(!tmp)
  {
    if (!str_append_str(&ret, b))
      return (NULL);
    int read_ret = read(fd, b, BUFFER_SIZE);
    if (read_ret == -1)
      return (NULL);
    b[read_ret] = 0;
  }
  if (!str_append_mem(&ret, b, tmp - b + 1))
  {
    free(ret);
    return NULL;
  }
  return ret;
}

/*
 * EJERCICIO: FILTER
 * 
 * DESCRIPCIÓN: 
 * Leer de stdin y escribir a stdout, pero reemplazando todas las ocurrencias
 * de una cadena dada por asteriscos (*) de la misma longitud.
 * 
 * CONCEPTOS CLAVE:
 * 1. LECTURA DINÁMICA: read() con buffer variable
 * 2. BÚSQUEDA DE PATRONES: strstr() o memmem()
 * 3. GESTIÓN DE MEMORIA: realloc() para buffer dinámico
 * 4. MANEJO DE ERRORES: perror() para errores de sistema
 * 
 * ALGORITMO:
 * 1. Leer todo el contenido de stdin en un buffer dinámico
 * 2. Buscar todas las ocurrencias del patrón
 * 3. Reemplazar cada ocurrencia con asteriscos
 * 4. Escribir el resultado a stdout
 */

#define _GNU_SOURCE  // Para memmem()
#ifndef BUFFER_SIZE
# define BUFFER_SIZE 42
#endif

#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <string.h>

// Función para encontrar y reemplazar todas las ocurrencias
void ft_filter(char *buffer, const char *target)
{
    int i = 0;
    int target_len = strlen(target);
    int j, k;

    /*
     * ALGORITMO DE BÚSQUEDA Y REEMPLAZO:
     * - Recorrer el buffer carácter por carácter
     * - En cada posición, verificar si coincide con el patrón
     * - Si coincide, escribir asteriscos y saltar la longitud del patrón
     * - Si no coincide, escribir el carácter original
     */

    while (buffer[i])
    {
        j = 0;
        // Verificar si hay coincidencia desde la posición actual
        while (target[j] && (buffer[i + j] == target[j]))
            j++;

        if (j == target_len) // Coincidencia completa encontrada
        {
            // Escribir asteriscos en lugar del patrón
            k = 0;
            while (k < target_len)
            {
                write(1, "*", 1);
                k++;
            }
            i += target_len; // Saltar el patrón completo
        }
        else
        {
            // No hay coincidencia, escribir carácter original
            write(1, &buffer[i], 1);
            i++;
        }
    }
}

int main(int argc, char **argv)
{
    /*
     * VALIDACIÓN DE ARGUMENTOS:
     * - Debe haber exactamente 1 argumento
     * - El argumento no puede estar vacío
     */
    if (argc != 2 || argv[1][0] == '\0')
        return 1;

    /*
     * LECTURA DINÁMICA DE STDIN:
     * - Usar buffer temporal para leer chunks
     * - Usar realloc() para expandir el buffer principal
     * - Mantener seguimiento del total leído
     */
    char temp[BUFFER_SIZE];
    char *result = NULL;
    char *buffer;
    int total_read = 0;
    ssize_t bytes;

    // Leer de stdin hasta EOF
    while ((bytes = read(0, temp, BUFFER_SIZE)) > 0)
    {
        // Expandir el buffer principal para acomodar los nuevos datos
        buffer = realloc(result, total_read + bytes + 1);
        if (!buffer)
        {
            free(result);
            perror("realloc");
            return 1;
        }

        result = buffer;

        // Copiar los nuevos datos al buffer principal
        memmove(result + total_read, temp, bytes);
        total_read += bytes;
        result[total_read] = '\0'; // Asegurar terminación
    }

    // Verificar errores de lectura
    if (bytes < 0)
    {
        perror("read");
        free(result);
        return 1;
    }

    // Si no se leyó nada, salir sin error
    if (!result)
        return 0;

    // Procesar el buffer y aplicar el filtro
    ft_filter(result, argv[1]);

    // Liberar memoria
    free(result);
    return 0;
}

/*
 * PUNTOS CLAVE PARA EL EXAMEN:
 * 
 * 1. GESTIÓN DE MEMORIA:
 *    - Siempre verificar el retorno de malloc/realloc
 *    - Liberar memoria en caso de error
 *    - Usar memmove() en lugar de memcpy() para solapamientos
 * 
 * 2. MANEJO DE ERRORES:
 *    - Usar perror() para errores de sistema
 *    - Retornar códigos de error apropiados
 *    - Validar argumentos antes de usarlos
 * 
 * 3. LECTURA DINÁMICA:
 *    - El buffer puede llenarse con cualquier cantidad de datos
 *    - Usar realloc() para expandir según sea necesario
 *    - Mantener un terminador nulo válido
 * 
 * 4. ALGORITMO EFICIENTE:
 *    - Búsqueda simple carácter por carácter
 *    - Evitar usar funciones no permitidas
 *    - Escribir directamente a stdout sin almacenar el resultado
 */

#include <unistd.h>
#include <stdlib.h>

int	ft_abs(int x)
{
	if (x < 0)
		return (-x);
	return (x);
}

void	ft_putnbr(int n)
{
	char c;

	if (n >= 10)
		ft_putnbr(n / 10);
	c = (n % 10) + '0';
	write(1, &c, 1);
}

void	print_solution(int *pos, int n)
{
	int i = 0;

	while (i < n)
	{
		ft_putnbr(pos[i]);
		if (i < n - 1)
			write(1, " ", 1);
		i++;
	}
	write(1, "\n", 1);
}

int	is_safe(int *pos, int col, int row)
{
	int i = 0;

	while (i < col)
	{
		if (pos[i] == row)
			return (0);
		if (ft_abs(pos[i] - row) == col - i)
			return (0);
		i++;
	}
	return (1);
}

void	solve(int *pos, int n, int col)
{
	int row = 0;

	if (col == n)
	{
		print_solution(pos, n);
		return ;
	}
	while (row < n)
	{
		if (is_safe(pos, col, row))
		{
			pos[col] = row;
			solve(pos, n, col + 1);
		}
		row++;
	}
}

int	main(int ac, char **av)
{
	int n;
	int *pos;

	if (ac != 2)
		return (1);
	n = atoi(av[1]);
	if (n <= 0)
		return (0);

	pos = malloc(sizeof(int) * n);
	if (!pos)
		return (1);

	solve(pos, n, 0);
	free(pos);
	return (0);
}

/*
 * EJERCICIO: PERMUTATIONS
 * 
 * DESCRIPCIÓN:
 * Generar todas las permutaciones de un string dado en orden alfabético.
 * 
 * CONCEPTOS CLAVE:
 * 1. BACKTRACKING: Algoritmo de exploración exhaustiva
 * 2. ORDENAMIENTO: Asegurar orden alfabético
 * 3. RECURSIÓN: Generar permutaciones nivel por nivel
 * 4. ESTADO: Manejar qué caracteres ya se han usado
 * 
 * ALGORITMO:
 * 1. Ordenar el string original alfabéticamente
 * 2. Para cada posición, probar cada carácter no usado
 * 3. Marcar carácter como usado y recursar
 * 4. Desmarcar carácter al retornar (backtrack)
 * 5. Imprimir cuando se complete una permutación
 */

#include <unistd.h>
#include <stdlib.h>
#include <stdio.h>

// Función auxiliar para calcular longitud
int ft_strlen(char *s)
{
    int i = 0;
    while (s[i])
        i++;
    return i;
}

// Función auxiliar para verificar si es alfabético
int ft_isalpha(int c)
{
    return ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z'));
}

// Función para intercambiar dos caracteres
void ft_swap(char *a, char *b)
{
    char temp = *a;
    *a = *b;
    *b = temp;
}

// Función para verificar si carácter ya está en uso
int ft_strchr(const char *s, char c)
{
    int i = 0;
    while (s[i])
    {
        if (s[i] == c)
            return 1; // Encontrado
        i++;
    }
    return 0; // No encontrado
}

// Función para ordenar string alfabéticamente (bubble sort)
char *order_string(char *s)
{
    /*
     * ORDENAMIENTO BURBUJA:
     * - Comparar caracteres adyacentes
     * - Intercambiar si están en orden incorrecto
     * - Repetir hasta que no haya intercambios
     * - Garantiza orden alfabético para las permutaciones
     */
    int len = ft_strlen(s);
    int swapped = 1;

    while (swapped)
    {
        swapped = 0;
        int i = 0;
        while (i < len - 1)
        {
            if (s[i] > s[i + 1])
            {
                ft_swap(&s[i], &s[i + 1]);
                swapped = 1;
            }
            i++;
        }
    }
    return s;
}

// Función recursiva para generar permutaciones
void generate_permutations(char *source, char *result, int pos)
{
    /*
     * ALGORITMO BACKTRACKING PARA PERMUTACIONES:
     * 
     * CASO BASE: Si pos == longitud, tenemos una permutación completa
     * - Imprimir la permutación actual
     * - Retornar para probar otras opciones
     * 
     * CASO RECURSIVO: Para cada carácter en source:
     * - Si no está usado en result, probarlo
     * - Agregarlo a result[pos]
     * - Recursar para la siguiente posición
     * - Remover carácter (backtrack) para probar otros
     */

    int source_len = ft_strlen(source);

    // Caso base: permutación completa
    if (pos == source_len)
    {
        write(1, result, source_len);
        write(1, "\n", 1);
        return;
    }

    // Probar cada carácter de source
    int i = 0;
    while (i < source_len)
    {
        // Verificar si el carácter ya está usado
        if (!ft_strchr(result, source[i]))
        {
            result[pos] = source[i];        // Usar carácter
            generate_permutations(source, result, pos + 1);  // Recursar
            result[pos] = '\0';             // Backtrack: remover carácter
        }
        i++;
    }
}

int main(int argc, char **argv)
{
    /*
     * VALIDACIÓN Y PROCESAMIENTO:
     * - Verificar argumentos válidos
     * - Validar que solo contiene letras
     * - Ordenar string alfabéticamente
     * - Inicializar buffer para resultado
     * - Generar todas las permutaciones
     */

    if (argc != 2)
        return 1;

    // Verificar string vacío o solo espacios
    if (ft_strlen(argv[1]) == 0 || (argv[1][0] == ' ' && !argv[1][1]))
        return 0;

    // Validar que solo contiene caracteres alfabéticos
    int i = 0;
    while (argv[1][i])
    {
        if (!ft_isalpha(argv[1][i]))
            return 0;
        i++;
    }

    int len = ft_strlen(argv[1]);

    // Alocar buffer para el resultado (permutación actual)
    char *result = calloc(len + 1, 1);
    if (!result)
        return 1;

    // Ordenar el string alfabéticamente
    char *source = order_string(argv[1]);

    // Generar todas las permutaciones
    generate_permutations(source, result, 0);

    free(result);
    return 0;
}

/*
 * EJEMPLO DE EJECUCIÓN:
 * 
 * ./permutations abc
 * abc
 * acb  
 * bac
 * bca
 * cab
 * cba
 * 
 * PROCESO PARA "abc":
 * 1. Ordenar: "abc" (ya está ordenado)
 * 2. pos=0: Probar 'a', 'b', 'c'
 *    - Elegir 'a': result="a"
 *      - pos=1: Probar 'b', 'c' (no 'a' porque está usado)
 *        - Elegir 'b': result="ab"
 *          - pos=2: Probar 'c': result="abc" → IMPRIMIR
 *        - Elegir 'c': result="ac"  
 *          - pos=2: Probar 'b': result="acb" → IMPRIMIR
 *    - Elegir 'b': result="b"
 *      - Similar proceso...
 */

/*
 * VERSIÓN ALTERNATIVA CON ALGORITMO DE HEAP:
 * (Más eficiente para strings largos)
 */
void heap_permute(char *str, int size)
{
    // Caso base
    if (size == 1)
    {
        puts(str);
        return;
    }

    int i;
    for (i = 0; i < size; i++)
    {
        heap_permute(str, size - 1);

        // Si size es impar, intercambiar primer y último
        // Si size es par, intercambiar i-ésimo y último
        if (size % 2 == 1)
            ft_swap(&str[0], &str[size - 1]);
        else
            ft_swap(&str[i], &str[size - 1]);
    }
}

/*
 * PUNTOS CLAVE PARA EL EXAMEN:
 * 
 * 1. ORDEN ALFABÉTICO:
 *    - CRUCIAL ordenar el string antes de generar permutaciones
 *    - Sin ordenamiento, no se garantiza orden alfabético
 *    - Usar algoritmo de ordenamiento simple pero correcto
