/*
 * ALGORITMO OPTIMIZADO (para casos complejos):
 * 
 * void rip_optimized(char *str)
 * {
 *     // Contar paréntesis desbalanceados
 *     int open = 0, close = 0;
 *     
 *     // Primera pasada: contar ')' excedentes
 *     for (int i = 0; str[i]; i++)
